Here is the recipe JSON:
{
  "recipe_name": "Indie House Pizza",
  "ingredients": [
    "1 1/2 cups warm water",
    "1 tablespoon sugar",
    "2 teaspoons active dry yeast",
    "3 1/2 cups all-purpose flour",
    "1 teaspoon salt",
    "2 tablespoons olive oil",
    "1/2 cup pizza sauce",
    "1 cup shredded mozzarella cheese",
    "1/2 cup shredded parmesan cheese",
    "Toppings of your choice (e.g. pepperoni, mushrooms, onions, bell peppers)"
  ],
  "steps": [
    {
      "step_number": 1,
      "instruction": "In a large mixing bowl, combine warm water, sugar, and yeast. Let it sit for 5-10 minutes until the yeast is activated.",
      "time": "10 minutes",
      "tip": "Make sure the water is not too hot, as it can kill the yeast."
    },
    {
      "step_number": 2,
      "instruction": "Add flour, salt, and olive oil to the bowl. Mix until a dough forms.",
      "time": "5 minutes",
      "tip": "Use a stand mixer with a dough hook attachment to make the process easier."
    },
    {
      "step_number": 3,
      "instruction": "Knead the dough on a floured surface for 5-10 minutes until it becomes smooth and elastic.",
      "time": "10 minutes",
      "tip": "Add more flour if the dough is too sticky, and more water if it's too dry."
    },
    {
      "step_number": 4,
      "instruction": "Place the dough in a greased bowl, cover it with plastic wrap, and let it rise in a warm place for 1-2 hours until it has doubled in size.",
      "time": "1-2 hours",
      "tip": "Keep the bowl away from drafts and extreme temperatures."
    },
    {
      "step_number": 5,
      "instruction": "Preheat the oven to 425\u00b0F (220\u00b0C). Punch down the dough and roll it out into a circle or rectangle shape.",
      "time": "10 minutes",
      "tip": "Use a pizza peel or a piece of parchment paper to transfer the dough to the oven."
    },
    {
      "step_number": 6,
      "instruction": "Spread the pizza sauce over the dough, leaving a small border around the edges. Add mozzarella and parmesan cheese, and your desired toppings.",
      "time": "5 minutes",
      "tip": "Don't overload the pizza with too many toppings, as it can make the crust soggy."
    },
    {
      "step_number": 7,
      "instruction": "Bake the pizza in the preheated oven for 15-20 minutes until the crust is golden brown and the cheese is melted and bubbly.",
      "time": "15-20 minutes",
      "tip": "Rotate the pizza halfway through the baking time to ensure even cooking."
    }
  ]
}
